input.command:
mkdir -p /tmp/qp3037 && cat > /tmp/qp3037/probe.py <<'EOF'
import base64, json, pathlib, sys, urllib.request, urllib.error
env = {}
for l in pathlib.Path("/Users/raufaliyev/orca/workspaces/xsolla-ai-kit/qp-3037/.env").read_text().splitlines():
    if "=" in l and not l.strip().startswith("#"):
        k, v = l.split("=", 1); env[k.strip()] = v.strip().strip('"').strip("'")
P, M, K = env["XSOLLA_PROJECT_ID"], env["XSOLLA_MERCHANT_ID"], env["XSOLLA_PROJECT_API_KEY"]
def get(url, user=None, key=K):
    req = urllib.request.Request(url.replace("{P}", P))
    if user is not None:
        req.add_header("Authorization", "Basic " + base64.b64encode(f"{user}:{key}".encode()).decode())
    try:
        with urllib.request.urlopen(req, timeout=20) as r: return r.status, r.read().decode()
    except urllib.error.HTTPError as e: return e.code, e.read().decode()
    except Exception as e: return None, repr(e)
mode = sys.argv[1]
base = "https://store.xsolla.com/api/v2/project/{P}/admin/items/virtual_items"
if mode == "auth":
    for name, u in [("project_id", P), ("merchant_id", M), ("none", None)]:
        s, b = get(base + "?limit=1&offset=0", u); print(name, s, b[:300])
    s, b = get(base + "?limit=1&offset=0", P, "wrong-key"); print("project_id+badkey", s, b[:300])
elif mode == "limits":
    for lim in [50, 51, 100, 101, 200, 500, 1000]:
        s, b = get(base + f"?limit={lim}&offset=0", P)
        try: j = json.loads(b); print(lim, s, len(j.get("items", [])), j.get("has_more"), j.get("total_items_count"), list(j)[:6])
        except Exception: print(lim, s, b[:200])
elif mode == "all":
    items, off = [], 0
    while True:
        s, b = get(base + f"?limit=50&offset={off}", P); j = json.loads(b)
        items += j["items"]
        if not j.get("has_more"): break
        off += 50
    print("total", len(items), j.get("total_items_count"))
    print(json.dumps(items[0], indent=1, ensure_ascii=False)[:2500])
    for it in items:
        print(it["sku"], "|", json.dumps(it.get("name"), ensure_ascii=False)[:80], "|", it.get("type"), it.get("virtual_item_type"), "en=",it.get("is_enabled"), "show=",it.get("is_show_in_store"), "grp=",[g.get("external_id") for g in it.get("groups") or []], "attr=",[a.get("external_id") for a in it.get("attributes") or []])
    json.dump(items, open("/tmp/qp3037/admin_items.json","w"))
elif mode == "url":
    s, b = get(sys.argv[2], P if len(sys.argv) < 4 else None); print(s, b[:1500])
EOF
cd /tmp/qp3037 && python3 probe.py auth

