cd /tmp/qp3037 && cat > parity.py <<'EOF'
import json, ssl, urllib.request, pathlib
env = dict(l.split("=",1) for l in pathlib.Path("/Users/raufaliyev/orca/workspaces/xsolla-ai-kit/qp-3037/.env").read_text().splitlines() if "=" in l and not l.startswith("#"))
P = env["XSOLLA_PROJECT_ID"].strip().strip('"')
H = "https://web3-minting-service.gcp-k8s-web3-prod.srv.local"
ctx = ssl.create_default_context()
def get(u):
    try:
        with urllib.request.urlopen(u, timeout=20, context=ctx) as r: return r.status, r.read().decode()
    except urllib.error.HTTPError as e: return e.code, e.read().decode()
    except Exception as e:
        try:
            with urllib.request.urlopen(u, timeout=20, context=ssl._create_unverified_context()) as r: return ("noverify", r.status), r.read().decode()
        except Exception as e2: return None, repr(e) + " / " + repr(e2)
mint, off = [], 0
while True:
    s, b = get(f"{H}/skus?project={P}&limit=100&offset={off}")
    if off == 0: print("status", s, b[:600])
    try: j = json.loads(b)
    except Exception: print("bad", s, b[:300]); break
    print("page", off, s, j.get("projectId") == P, j.get("count"), len(j.get("items", [])), [k for k in j])
    if not j.get("items"): break
    mint += j["items"]; off += 100
json.dump(mint, open("mint.json","w"))
admin = json.load(open("admin_items.json"))
ms = {i.get("sku") for i in mint}; asku = {i["sku"]: i for i in admin}
print("mint", len(ms), "admin", len(asku))
print("mint not in admin:", sorted(ms - set(asku)))
print("admin not in mint:", sorted(set(asku) - ms))
for s in sorted(set(asku) - ms): i = asku[s]; print(" ", s, i["is_enabled"], i["is_show_in_store"], [g["external_id"] for g in i["groups"]], [a["external_id"] for a in i["attributes"]])
if mint: print("mint item sample:", json.dumps(mint[0])[:500])
names = {i.get("sku"): i.get("name") for i in mint}
print("name mismatches:", [(s, names[s], asku[s]["name"].get("en")) for s in ms & set(asku) if names[s] != asku[s]["name"].get("en")][:10])
EOF
python3 parity.py

